CREATE TABLE rate (
    sheet_id   VARCHAR(200)   NOT NULL REFERENCES sheet (id),
    grade      VARCHAR(1)     NOT NULL,
    pct        DECIMAL(19, 2) NOT NULL CHECK (pct >= 0),
    set_by     VARCHAR(200)   NOT NULL,
    set_at     TIMESTAMP      NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (sheet_id, grade)
);
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a claim uses
-- the one whose from-date is the latest on or before its date. No from-date applies from the
-- beginning of time (at most one such rate per grade).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before its date) has no rate. Null: no end.
ALTER TABLE rate ADD COLUMN to_date DATE;
-- A rate is kept as versions: setting a rate for a grade and from-date that already has one keeps the
-- value it replaces here as an older version, and the rate (the newest version, the one in force)
-- carries its version number (how many versions it has, counting itself).
ALTER TABLE rate ADD COLUMN version INT NOT NULL DEFAULT 1;
ALTER TABLE rate_history ADD COLUMN version INT NOT NULL DEFAULT 1;
